process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
import { chromium } from 'playwright';
import fs from 'fs';
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const K=Buffer.from('','base64').toString();
const P=Buffer.from('','base64').toString();
async function put(path, buf, msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'m', content:buf.toString('base64')};
  if(sha) body.sha=sha;
  const r2=await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
  console.log('put',path,r2.status);
}
async function main(){
  const out={};
  fs.writeFileSync('/tmp/kort.html', K); fs.writeFileSync('/tmp/priem.html', P);
  const b=await chromium.launch();
  const ctx=await b.newContext({viewport:{width:1400,height:1500}});

  /* --- KORTELE --- */
  let pg=await ctx.newPage();
  const kl1=[]; pg.on('pageerror',e=>kl1.push(String(e).slice(0,120)));
  await pg.goto('file:///tmp/kort.html',{waitUntil:'networkidle'});
  await pg.waitForTimeout(800);
  await pg.screenshot({path:'/tmp/n_kort.png',fullPage:true});
  out.kortele_klaidos=kl1;
  await pg.close();

  /* --- PRIEMIMAS: pilna eiga --- */
  pg=await ctx.newPage();
  const kl2=[]; pg.on('pageerror',e=>kl2.push(String(e).slice(0,120)));
  await pg.goto('file:///tmp/priem.html',{waitUntil:'networkidle'});
  await pg.waitForTimeout(600);
  await pg.screenshot({path:'/tmp/n_priem_tuscia.png'});

  /* 1. paieska + Enter */
  await pg.fill('#q','ausys');
  await pg.waitForTimeout(350);
  out.rado=await pg.locator('#rez .r').count();
  await pg.press('#q','Enter');
  await pg.waitForTimeout(400);
  out.eiluciu_po_pridejimo=await pg.locator('#tbody tr').count();

  /* 2. klaviatura: kiekis -> Enter -> savikaina -> Enter -> data -> Enter */
  await pg.keyboard.type('24');
  await pg.keyboard.press('Enter'); await pg.waitForTimeout(150);
  await pg.keyboard.type('0.58');
  await pg.keyboard.press('Enter'); await pg.waitForTimeout(150);
  await pg.keyboard.type('2027-03-01');
  await pg.keyboard.press('Enter'); await pg.waitForTimeout(300);
  out.suma_po_1=await pg.locator('#s-suma').innerText();
  out.fokusas_grizo=await pg.evaluate(()=>document.activeElement.id);

  /* 3. dar viena preke */
  await pg.fill('#q','plauciai'); await pg.waitForTimeout(300);
  await pg.press('#q','Enter'); await pg.waitForTimeout(300);
  await pg.keyboard.type('10'); await pg.keyboard.press('Enter');
  await pg.keyboard.type('1.25'); await pg.keyboard.press('Enter');
  await pg.waitForTimeout(300);
  out.pozicijos=await pg.locator('#s-poz').innerText();
  out.vienetai=await pg.locator('#s-vnt').innerText();
  out.suma=await pg.locator('#s-suma').innerText();

  /* 4. saskaitos tikrinimas */
  await pg.fill('#s-tikr','26.42'); await pg.waitForTimeout(300);
  out.skirtumas=await pg.locator('#s-skirt').innerText();
  await pg.screenshot({path:'/tmp/n_priem.png',fullPage:true});

  /* 5. PLN kursas */
  await pg.selectOption('#valiuta','PLN'); await pg.waitForTimeout(400);
  out.suma_pln=await pg.locator('#s-suma').innerText();
  out.kursas_matomas=await pg.locator('#kursas').isVisible();

  /* 6. kartoti praeita */
  await pg.selectOption('#valiuta','EUR');
  await pg.click('text=Kartoti praeitą tiekimą'); await pg.waitForTimeout(500);
  out.kartoti_eiluciu=await pg.locator('#tbody tr').count();
  await pg.screenshot({path:'/tmp/n_priem_kartoti.png',fullPage:true});
  out.priemimas_klaidos=kl2;
  await pg.close();

  await b.close();
  for(const f of ['n_kort','n_priem_tuscia','n_priem','n_priem_kartoti']){
    try{ await put('screenshots/'+f+'.png', fs.readFileSync('/tmp/'+f+'.png'), f); }catch(e){}
  }
  await put('analize/maketai.json', Buffer.from(JSON.stringify(out,null,2)),'maketai');
}
main().catch(async e=>{ await put('analize/maketai.json',Buffer.from(JSON.stringify({klaida:String(e)})),'err'); });
